response:
import { prisma } from '@/lib/prisma';
import Link from 'next/link';

export default async function PostsPage({ searchParams }) {
  const { page } = await searchParams;
  const current = Math.max(1, Number(page) || 1);
  const perPage = 10;
  const [posts, total] = await Promise.all([
    prisma.post.findMany({
      skip: (current - 1) * perPage,
      take: perPage,
      orderBy: { createdAt: 'desc' },
    }),
    prisma.post.count(),
  ]);
  const totalPages = Math.ceil(total / perPage);
  return (
    <div>
      {posts.map((p) => (
        <Link key={p.id} href={`/posts/${p.slug}`}>{p.title}</Link>
      ))}
      <div>
        {current > 1 && <Link href={`?page=${current - 1}`}>Trước</Link>}
        Trang {current}/{totalPages}
        {current < totalPages && <Link href={`?page=${current + 1}`}>Sau</Link>}
      </div>
    </div>
  );
}
Lưu ý: searchParams là Promise trong App Router, phải await trước khi dùng.

Dùng auth() export từ auth.ts (NextAuth v5) trong middleware. Tạo middleware.ts ở root:
import NextAuth from 'next-auth';
import { authConfig } from './auth.config';

export default NextAuth(authConfig).auth((req) => {
  const isLoggedIn = !!req.auth;
  const { pathname } = req.nextUrl;
  const isProtected = ['/dashboard', '/admin'].some((p) => pathname.startsWith(p));
  if (!isLoggedIn && isProtected) {
    const url = new URL('/login', req.nextUrl);
    url.searchParams.set('callbackUrl', pathname);
    return Response.redirect(url);
  }
  return NextResponse.next();
});

export const config = { matcher: ['/dashboard/:path*', '/admin/:path*'] };
Lưu ý: middleware chạy ở edge nên chỉ verify JWT, không đọc session từ database. Giữ secret trong env, không hardcode.

type NonEmpty<T> = {
  [K in keyof T]: T[K] extends null | undefined | '' ? never : K;
}[keyof T];

function compactObject<T extends Record<string, unknown>>(obj: T): Pick<T, NonEmpty<T>> {
  return Object.fromEntries(
    Object.entries(obj).filter(([, v]) => v !== null && v !== undefined && v !== '')
  ) as Pick<T, NonEmpty<T>>;
}

const cleaned = compactObject({ name: 'An', age: 0, bio: '', nick: null });
// cleaned: { name: 'An', age: 0 }
Lưu ý: 0 giữ nguyên vì khác '' và null. Muốn bỏ cả 0 và false thì mở rộng predicate. Mapped type NonEmpty đảm bảo key bị bỏ cũng biến mất khỏi type.

model User {
  id        String   @id @default(cuid())
  email     String   @unique
  roles     UserRole[]
  createdAt DateTime @default(now())
}

model Role {
  id    String     @id @default(cuid())
  name  String     @unique
  users UserRole[]
}

model UserRole {
  userId     String
  roleId     String
  user       User   @relation(fields: [userId], references: [id], onDelete: Cascade)
  role       Role   @relation(fields: [roleId], references: [id], onDelete: Cascade)
  assignedAt DateTime @default(now())
  @@id([userId, roleId])
}
Dùng bảng join UserRole rõ ràng thay vì implicit relation để chứa metadata như assignedAt. Truy vấn: prisma.user.findUnique({ where: { id }, include: { roles: { include: { role: true } } } }). Chạy npx prisma migrate dev để sinh bảng.

// server/auth.ts
import { initTRPC, TRPCError } from '@trpc/server';

export const t = initTRPC.context().create();

export const isAuthed = t.middleware(({ ctx, next }) => {
  if (!ctx.user) {
    throw new TRPCError({ code: 'UNAUTHORIZED' });
  }
  return next({ ctx: { user: ctx.user } });
});

export const protectedProcedure = t.procedure.use(isAuthed);

// server/router/user.ts
export const userRouter = t.router({
  me: protectedProcedure.query(async ({ ctx }) => ctx.user),
});
Cách này gọn vì check auth nằm ở middleware, procedure chỉ dùng ctx.user. Nhớ nhét user vào context từ resolver (đọc cookie session) mỗi request.

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface CartState {
  items: { id: string; qty: number }[];
  add: (id: string) => void;
}

export const useCart = create<CartState>()(
  persist(
    (set) => ({
      items: [],
      add: (id) =>
        set((s) => ({
          items: s.items.some((i) => i.id === id)
            ? s.items.map((i) => (i.id === id ? { ...i, qty: i.qty + 1 } : i))
            : [...s.items, { id, qty: 1 }],
        })),
    }),
    { name: 'cart-storage', partialize: (s) => ({ items: s.items }) }
  )
);
partialize giới hạn chỉ lưu dữ liệu, không lưu function. Với app có SSR, tạo store mới bên trong useRef để tránh dùng chung state giữa các request, và chỉ đọc localStorage ở client.

'use client';
import { cacheExchange, fetchExchange, createClient, ssrExchange } from '@urql/core';
import { Provider } from 'urql';

const isServer = typeof window === 'undefined';
const ssr = ssrExchange({ isClient: !isServer });

const client = createClient({
  url: process.env.NEXT_PUBLIC_API_URL!,
  exchanges: [cacheExchange, ssr, fetchExchange],
});

export function Providers({ children }) {
  return <Provider value={client}>{children}</Provider>;
}
Trong Server Component dùng client mới cho mỗi request (ssrExchange isClient: false), gọi query, lấy data truyền xuống Client Component; bọc app trong Providers. urql không lấy data server-side tự động — phải tự gọi query ở server rồi hydrate qua ssrExchange, sau đó client render tiếp mà không gọi lại API.

Zod là cách chuẩn để validate input tRPC, type tự suy từ schema:
import { z } from 'zod';

const createPostSchema = z.object({
  title: z.string().min(1).max(120),
  content: z.string().min(10),
  tags: z.array(z.string()).max(5).default([]),
});

export const postRouter = t.router({
  create: publicProcedure
    .input(createPostSchema)
    .mutation(async ({ ctx, input }) => {
      return ctx.prisma.post.create({ data: input });
    }),
});
Client tự có type của input, sai field hay sai kiểu báo ngay lúc gọi. Muốn tự sinh form validation thì tái sử dụng cùng schema ở client. Error message tiếng Việt: đặt message trong từng refine hoặc dùng zodErrorMap toàn cục.

export function middleware(req: NextRequest) {
  const token = req.cookies.get('session')?.value;
  const isLoginPage = req.nextUrl.pathname === '/login';

  if (!token && !isLoginPage && req.nextUrl.pathname.startsWith('/account')) {
    const url = new URL('/login', req.nextUrl);
    url.searchParams.set('from', req.nextUrl.pathname);
    return NextResponse.redirect(url);
  }

  if (token && isLoginPage) {
    return NextResponse.redirect(new URL('/account', req.nextUrl));
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/account/:path*', '/login'],
};
Nhớ: middleware chạy ở edge nên không đọc DB — chỉ verify cookie/token nhẹ. Redirect kèm param 'from' để sau khi login quay lại trang gốc. Nếu đã dùng NextAuth thì bọc bằng NextAuth(authConfig).auth để có req.auth.

Vì SSR render trên server không có window, dùng trực tiếp sẽ lỗi ReferenceError. Ba cách tùy tình huống: (1) Nếu component chạy client thuần, thêm 'use client' và đọc window trong useEffect:
const [mounted, setMounted] = useState(false);
useEffect(() => setMounted(true), []);
if (!mounted) return <div className=""h-screen""></div>;
return <Chart width={window.innerWidth} />;
(2) Dùng dynamic() với ssr: false để import lazy chỉ ở client: const Chart = dynamic(() => import('./Chart'), { ssr: false });. (3) Truyền dữ liệu từ Server Component xuống, client chỉ render khi prop chắc chắn. Cách 1 chuẩn nhất để tránh hydration mismatch.
